// Monthly EPF contributions. All amounts are in paise.

// Premise in-epf-ceiling@1 (final): ₹15,000 a month.
export const EPF_WAGE_CEILING_PAISE = 1_500_000;
// Premise in-epf-rate@1 (draft): 12% each from employee and employer.
export const EPF_RATE_PERCENT = 12;
// Premise in-eps-rate@1 (draft): 8.33% of the employer's 12% goes to EPS.
export const EPS_RATE_BASIS_POINTS = 833;
// Premise in-epf-rounding@1 (draft): each contribution to the nearest rupee, 50 paise rounding up.
export const EPF_ROUNDING_PAISE = 100;

export interface EpfContribution {
  /** Basic wages the contributions were computed on, after the ceiling. */
  wagesConsidered: number;
  employee: number;
  employerEpf: number;
  employerEps: number;
}

/** basicWages × basisPoints / 10,000, rounded half-up to the rupee, in integer arithmetic. */
function contribution(basicWages: number, basisPoints: number): number {
  const scale = 10_000 * EPF_ROUNDING_PAISE;
  return Math.floor((basicWages * basisPoints + scale / 2) / scale) * EPF_ROUNDING_PAISE;
}

export function monthlyEpf(basicWagesPaise: number): EpfContribution {
  if (!Number.isInteger(basicWagesPaise) || basicWagesPaise < 0) {
    throw new RangeError(`basic wages must be a non-negative integer of paise, got ${basicWagesPaise}`);
  }
  const wagesConsidered = Math.min(basicWagesPaise, EPF_WAGE_CEILING_PAISE);
  const employee = contribution(wagesConsidered, EPF_RATE_PERCENT * 100);
  const employerEps = contribution(wagesConsidered, EPS_RATE_BASIS_POINTS);
  // The employer's share matches the employee's; what is not EPS stays in EPF.
  const employerEpf = employee - employerEps;
  return { wagesConsidered, employee, employerEpf, employerEps };
}

// Monthly ESI contributions. All amounts are in paise.

// Premise in-esi-ceiling@1 (final): covered when gross wages are ₹21,000 a month or less.
export const ESI_WAGE_CEILING_PAISE = 2_100_000;
// Premise in-esi-employee-rate@1 (draft): 0.75% of gross wages from the employee.
export const ESI_EMPLOYEE_RATE_BASIS_POINTS = 75;
// Premise in-esi-employer-rate@1 (draft): 3.25% of gross wages from the employer.
export const ESI_EMPLOYER_RATE_BASIS_POINTS = 325;
// Premise in-esi-rounding@1 (draft): each contribution rounded up to the next rupee.
export const ESI_ROUNDING_PAISE = 100;

export interface EsiContribution {
  covered: boolean;
  employee: number;
  employer: number;
}

function requireNonNegativeInteger(value: number, what: string): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new RangeError(`${what} must be a non-negative integer of paise, got ${value}`);
  }
}

/** grossWages × basisPoints / 10,000, rounded up to the rupee, in integer arithmetic. */
function contribution(grossWages: number, basisPoints: number): number {
  const scale = 10_000 * ESI_ROUNDING_PAISE;
  return Math.floor((grossWages * basisPoints + scale - 1) / scale) * ESI_ROUNDING_PAISE;
}

/**
 * Coverage is decided on the wages at the start of the contribution period and holds to its end,
 * so a raise above the ceiling mid-period does not stop contributions. Pass those wages as
 * `coverageWagesPaise`; they default to this month's. Contributions are on the full gross wages,
 * with no cap. The exemption of the lowest-paid from their own share is not applied here.
 */
export function monthlyEsi(grossWagesPaise: number, coverageWagesPaise = grossWagesPaise): EsiContribution {
  requireNonNegativeInteger(grossWagesPaise, "gross wages");
  requireNonNegativeInteger(coverageWagesPaise, "coverage wages");
  if (coverageWagesPaise > ESI_WAGE_CEILING_PAISE) {
    return { covered: false, employee: 0, employer: 0 };
  }
  return {
    covered: true,
    employee: contribution(grossWagesPaise, ESI_EMPLOYEE_RATE_BASIS_POINTS),
    employer: contribution(grossWagesPaise, ESI_EMPLOYER_RATE_BASIS_POINTS),
  };
}

// FLSA overtime exemption and weekly overtime. All amounts are in cents. Federal rules only.

// Premise us-flsa-salary@1 (final): $684 a week.
export const FLSA_SALARY_LEVEL_CENTS = 68_400;
// Premise us-flsa-ot-hours@1 (draft): overtime for hours beyond 40 in a workweek.
export const OVERTIME_THRESHOLD_HOURS = 40;
// Premise us-flsa-ot-rate@1 (draft): overtime at 150% of the regular rate.
export const OVERTIME_RATE_PERCENT = 150;

function requireNonNegativeInteger(value: number, what: string): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new RangeError(`${what} must be a non-negative integer, got ${value}`);
  }
}

/**
 * The salary level test: a salaried employee can be exempt from overtime only if paid at least
 * the salary level each week. Passing it is necessary, not sufficient — the salary basis and
 * duties tests are not checked here.
 */
export function meetsSalaryLevel(weeklySalaryCents: number): boolean {
  requireNonNegativeInteger(weeklySalaryCents, "weekly salary in cents");
  return weeklySalaryCents >= FLSA_SALARY_LEVEL_CENTS;
}

export interface WeeklyPay {
  regularMinutes: number;
  overtimeMinutes: number;
  regularPay: number;
  overtimePay: number;
  gross: number;
}

/** rateCents × minutes / 60 × percent / 100, rounded half-up to the cent, in integer arithmetic. */
function pay(hourlyRateCents: number, minutes: number, percent: number): number {
  const scale = 60 * 100;
  return Math.floor((hourlyRateCents * minutes * percent + scale / 2) / scale);
}

/** Weekly gross pay for a non-exempt employee paid by the hour. Time is in whole minutes. */
export function weeklyGross(hourlyRateCents: number, minutesWorked: number): WeeklyPay {
  requireNonNegativeInteger(hourlyRateCents, "hourly rate in cents");
  requireNonNegativeInteger(minutesWorked, "minutes worked");
  const regularMinutes = Math.min(minutesWorked, OVERTIME_THRESHOLD_HOURS * 60);
  const overtimeMinutes = minutesWorked - regularMinutes;
  const regularPay = pay(hourlyRateCents, regularMinutes, 100);
  const overtimePay = pay(hourlyRateCents, overtimeMinutes, OVERTIME_RATE_PERCENT);
  return { regularMinutes, overtimeMinutes, regularPay, overtimePay, gross: regularPay + overtimePay };
}

// Onboarding check: from a new hire's offered salary, which statutory coverage applies. The notes
// quote the figures from the payroll modules, never their own copies, so a rule change reaches HR
// with the calculation.

import { EPF_WAGE_CEILING_PAISE } from "../in/epf.ts";
import { ESI_WAGE_CEILING_PAISE, monthlyEsi } from "../in/esi.ts";
import { FLSA_SALARY_LEVEL_CENTS, OVERTIME_RATE_PERCENT, OVERTIME_THRESHOLD_HOURS, meetsSalaryLevel } from "../us/flsa.ts";

export interface IndianOffer {
  country: "IN";
  /** Offered monthly basic wages for PF, in paise: basic + DA + retaining allowance. */
  basicWagesPaise: number;
  /** Offered monthly gross wages, in paise. */
  grossWagesPaise: number;
}

export interface UsOffer {
  country: "US";
  /** Offered annual salary, in cents. */
  annualSalaryCents: number;
}

export interface IndianCoverage {
  country: "IN";
  /** PF membership is mandatory at or under the ceiling; above it the hire may decline it. */
  pf: "mandatory" | "optional";
  esi: boolean;
  notes: string[];
}

export interface UsCoverage {
  country: "US";
  /** Whether the salary allows an overtime exemption. Not whether the role is exempt. */
  canBeExempt: boolean;
  notes: string[];
}

const WEEKS_PER_YEAR = 52;

const inr = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });
const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

function requireNonNegativeInteger(value: number, what: string): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new RangeError(`${what} must be a non-negative integer, got ${value}`);
  }
}

/**
 * PF and ESI coverage for an Indian hire. Assumes the establishment is itself covered by both
 * schemes; the employee-count and notified-area conditions are not checked here.
 */
function indianCoverage(offer: IndianOffer): IndianCoverage {
  requireNonNegativeInteger(offer.basicWagesPaise, "basic wages in paise");
  requireNonNegativeInteger(offer.grossWagesPaise, "gross wages in paise");
  const pfCeiling = inr.format(EPF_WAGE_CEILING_PAISE / 100);
  const esiCeiling = inr.format(ESI_WAGE_CEILING_PAISE / 100);

  const pf = offer.basicWagesPaise <= EPF_WAGE_CEILING_PAISE ? "mandatory" : "optional";
  // A new hire's offered wages are the wages at the start of their first ESI contribution period.
  const esi = monthlyEsi(offer.grossWagesPaise).covered;

  return {
    country: "IN",
    pf,
    esi,
    notes: [
      pf === "mandatory"
        ? `PF: mandatory. Basic wages are ${pfCeiling} a month or less.`
        : `PF: optional. Basic wages are above ${pfCeiling} a month, so the hire may decline PF at joining —` +
          ` unless they are already a PF member from a previous job, in which case it continues.`,
      esi
        ? `ESI: covered. Gross wages are ${esiCeiling} a month or less.`
        : `ESI: not covered. Gross wages are above ${esiCeiling} a month.`,
    ],
  };
}

/** Federal FLSA salary level test only; state thresholds can be higher. */
function usCoverage(offer: UsOffer): UsCoverage {
  requireNonNegativeInteger(offer.annualSalaryCents, "annual salary in cents");
  // Flooring cannot change the outcome: floor(a / 52) ≥ level exactly when a ≥ 52 × level.
  const canBeExempt = meetsSalaryLevel(Math.floor(offer.annualSalaryCents / WEEKS_PER_YEAR));
  const level = `${usd.format(FLSA_SALARY_LEVEL_CENTS / 100)} a week` +
    ` (${usd.format((FLSA_SALARY_LEVEL_CENTS * WEEKS_PER_YEAR) / 100)} a year)`;

  return {
    country: "US",
    canBeExempt,
    notes: [
      canBeExempt
        ? `Overtime: the salary meets the federal level of ${level}, so the role can be exempt —` +
          ` only if it also passes the salary basis and duties tests, and any state test.`
        : `Overtime: the salary is below the federal level of ${level}, so the role cannot be exempt.` +
          ` Pay overtime at ${OVERTIME_RATE_PERCENT}% of the regular rate for hours beyond` +
          ` ${OVERTIME_THRESHOLD_HOURS} in a workweek.`,
    ],
  };
}

export function onboardingCoverage(offer: IndianOffer): IndianCoverage;
export function onboardingCoverage(offer: UsOffer): UsCoverage;
export function onboardingCoverage(offer: IndianOffer | UsOffer): IndianCoverage | UsCoverage;
export function onboardingCoverage(offer: IndianOffer | UsOffer): IndianCoverage | UsCoverage {
  return offer.country === "IN" ? indianCoverage(offer) : usCoverage(offer);
}

// Payslip text for an Indian employee: the PF, pension and ESI lines, each with a note saying when
// it applies. All amounts are in paise. The notes quote the figures from epf.ts and esi.ts, never
// their own copies, so a rule change reaches the payslip with the calculation.

import { EPF_RATE_PERCENT, EPF_WAGE_CEILING_PAISE, EPS_RATE_BASIS_POINTS, monthlyEpf } from "./epf.ts";
import {
  ESI_EMPLOYEE_RATE_BASIS_POINTS,
  ESI_EMPLOYER_RATE_BASIS_POINTS,
  ESI_WAGE_CEILING_PAISE,
  monthlyEsi,
} from "./esi.ts";

export interface IndianPayslipInput {
  employeeName: string;
  /** The month the payslip covers, as it should be printed, e.g. "October 2026". */
  period: string;
  /** Basic wages for PF: basic + DA + retaining allowance. */
  basicWagesPaise: number;
  grossWagesPaise: number;
  /** Gross wages at the start of the ESI contribution period; defaults to this month's. */
  esiCoverageWagesPaise?: number;
}

const amount = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR" });
const wholeRupees = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });

const money = (paise: number) => amount.format(paise / 100);
const ceiling = (paise: number) => wholeRupees.format(paise / 100);
const percent = (basisPoints: number) => `${basisPoints / 100}%`;

const LABEL_WIDTH = 30;
const AMOUNT_WIDTH = 14;
const NONE = "—";

function row(label: string, employee: string, employer: string): string {
  return (label.padEnd(LABEL_WIDTH) + employee.padStart(AMOUNT_WIDTH) + employer.padStart(AMOUNT_WIDTH)).trimEnd();
}

export function formatIndianPayslip(input: IndianPayslipInput): string {
  const pf = monthlyEpf(input.basicWagesPaise);
  const esi = monthlyEsi(input.grossWagesPaise, input.esiCoverageWagesPaise);
  const epfRate = percent(EPF_RATE_PERCENT * 100);

  return [
    `Payslip: ${input.employeeName}, ${input.period}`,
    "",
    row("Basic wages", money(input.basicWagesPaise), ""),
    row("Gross wages", money(input.grossWagesPaise), ""),
    "",
    row("", "You pay", "Employer pays"),
    row("Provident Fund (EPF)", money(pf.employee), money(pf.employerEpf)),
    `  ${epfRate} of basic wages up to ${ceiling(EPF_WAGE_CEILING_PAISE)} a month, from you and from your employer;` +
      ` the employer's ${epfRate} less the pension share goes here.`,
    row("Pension (EPS)", NONE, money(pf.employerEps)),
    `  ${percent(EPS_RATE_BASIS_POINTS)} of basic wages up to ${ceiling(EPF_WAGE_CEILING_PAISE)} a month,` +
      ` taken from the employer's ${epfRate}; nothing is deducted from your pay for it.`,
    row("Employees' State Insurance", esi.covered ? money(esi.employee) : NONE, esi.covered ? money(esi.employer) : NONE),
    `  Applies if gross wages were ${ceiling(ESI_WAGE_CEILING_PAISE)} a month or less when the contribution period began,` +
      ` until it ends: ${percent(ESI_EMPLOYEE_RATE_BASIS_POINTS)} of gross wages from you,` +
      ` ${percent(ESI_EMPLOYER_RATE_BASIS_POINTS)} from your employer.`,
  ].join("\n");
}

import { describe, expect, it } from "vitest";
import { onboardingCoverage } from "../src/hr/onboarding.ts";

const rupees = (r: number) => Math.round(r * 100);
const dollars = (d: number) => Math.round(d * 100);

const indian = (basic: number, gross: number) =>
  onboardingCoverage({ country: "IN", basicWagesPaise: basic, grossWagesPaise: gross });
const us = (annual: number) => onboardingCoverage({ country: "US", annualSalaryCents: annual });

describe("onboardingCoverage for an Indian hire", () => {
  it("makes PF mandatory and covers ESI for a low-paid hire", () => {
    const c = indian(rupees(10_000), rupees(18_000));
    expect(c.pf).toBe("mandatory");
    expect(c.esi).toBe(true);
    expect(c.notes).toEqual([
      "PF: mandatory. Basic wages are ₹15,000 a month or less.",
